SELECT mold_id AS moldId, COUNT(1) AS totalUsageCount, SUM(TIMESTAMPDIFF(SECOND, actual_start_time, actual_end_time) / 3600.0) AS totalProductionTime FROM mold_usage_records WHERE status = 3 AND actual_start_time IS NOT NULL AND actual_end_time IS NOT NULL AND actual_end_time >= #{start} AND actual_end_time <= #{end}
AND mold_id IN
#{moldId}
GROUP BY mold_id

SELECT
    mold_id AS moldId,
    COUNT(1) AS maintenanceCompletedCount
FROM maintenance_logs
WHERE
    COALESCE(actual_end_time, created_at) >= #{start}
    AND COALESCE(actual_end_time, created_at) <= #{end}

        AND mold_id IN

            #{moldId}


GROUP BY mold_id
